22	// DEVDESK-510 (NX-07), step 3: a group whose members are refused is not an empty
23	// group. The Cmd writes the refusal beside the listing and never over it (D23);
24	// only the handler, in Update, changes the model (Rule 110); an unreachable
25	// manager writes nothing (CA3); the refusal survives a restart and an old cache
26	// file gives "never", not "0" (CA6). Wording (footer, cell, status line) is
27	// step 4 and is not tested here.
28	
29	const groupSlug = "grp"
30	
31	// isolateGroupHome points HOME at a directory of the test's own: the group cache
32	// lives under it, and the package-wide HOME is shared by every test (DEVDESK-36).
33	func isolateGroupHome(t *testing.T) string {
34		t.Helper()
35		home := t.TempDir()
36		t.Setenv("HOME", home)
37		t.Setenv("USERPROFILE", home)
38		return home
39	}
40	
41	func groupCacheFile(home string) string {
42		return filepath.Join(home, ".devdesk", "cache", "registry-groups.json")
43	}
44	
45	// nexusGroupServer starts a Nexus that says "group" on the generic endpoint with
46	// no member listed there, so the format endpoint (path holding "/group/") decides.
47	func nexusGroupServer(t *testing.T, format http.HandlerFunc) config.RegistryItem {
48		t.Helper()
49		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
50			if !strings.Contains(r.URL.Path, "/group/") {
51				_, _ = w.Write([]byte(`{"type":"group","format":"docker","attributes":{"group":{"memberNames":[]}}}`))
52				return
53			}
54			format(w, r)
55		}))
56		t.Cleanup(srv.Close)
57		return config.RegistryItem{
58			Slug:     groupSlug,
59			Kind:     config.KindGroup,
60			Provider: config.ProviderNexus,
61			URL:      srv.URL + "/repository/docker-group",
62			AuthMode: config.AuthAnonymous,
63		}
64	}
65	
66	func replyStatus(code int) http.HandlerFunc {
67		return func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(code) }
68	}
69	
70	func replyMembers(names string) http.HandlerFunc {
71		return func(w http.ResponseWriter, _ *http.Request) {
72			_, _ = fmt.Fprintf(w, `{"group":{"memberNames":%s}}`, names)
73		}
74	}
