87	func openGroupCache(t *testing.T) *cache.RegistryGroupCache {
88		t.Helper()
89		c, err := cache.NewRegistryGroupCache()
90		if err != nil {
91			t.Fatalf("opening the group cache: %v", err)
92		}
93		return c
