96	// seedGroup writes what was last known for the slug: a listing, and when
97	// refusal is non-nil a refusal beside it.
98	func seedGroup(t *testing.T, listing *cache.RegistryGroupEntry, refusal *cache.RegistryGroupRefusal) {
99		t.Helper()
100		c := openGroupCache(t)
101		if listing != nil {
102			if err := c.Set(groupSlug, *listing); err != nil {
103				t.Fatalf("seeding the listing: %v", err)
104			}
105		}
106		if refusal != nil {
107			if err := c.SetRefusal(groupSlug, *refusal); err != nil {
108				t.Fatalf("seeding the refusal: %v", err)
109			}
110		}
111	}
