189	// CA2: a settled empty answer is written, and it supersedes a refusal.
190	func TestAnEmptyListingIsWrittenAndClearsTheRefusal(t *testing.T) {
191		isolateGroupHome(t)
192		known := knownMembers()
193		seedGroup(t, &known, &cache.RegistryGroupRefusal{At: at(4), Status: http.StatusForbidden})
194		reg := nexusGroupServer(t, replyMembers("[]"))
195	
196		msg := runDetect(t, reg)
197	
198		if msg.Err != nil {
199			t.Fatalf("msg.Err = %v, want nil: an empty group is a settled answer", msg.Err)
200		}
201		if msg.Members == nil || len(msg.Members) != 0 {
202			t.Errorf("msg.Members = %#v, want a non-nil empty list", msg.Members)
203		}
204		c := openGroupCache(t)
205		entry := c.Get(groupSlug)
206		if entry == nil {
207			t.Fatal("the empty listing was not written")
208		}
209		if len(entry.Members) != 0 {
210			t.Errorf("Members on disk = %+v, want none", entry.Members)
211		}
212		if entry.DiscoveredAt.IsZero() || !entry.DiscoveredAt.Equal(msg.At) {
213			t.Errorf("DiscoveredAt = %v, want msg.At = %v", entry.DiscoveredAt, msg.At)
214		}
215		if r := c.Refusal(groupSlug); r != nil {
216			t.Errorf("refusal on disk = %+v, want it cleared by a settled listing", *r)
217		}
218	}
