239	// CA3: not being able to ask is neither a listing nor a refusal. Nothing is
240	// written: not the listing, not a refusal, and an earlier refusal stays as is.
241	func TestAnUnreachableManagerWritesNothing(t *testing.T) {
242		shorten := func(t *testing.T) {
243			old := groupDetectTimeout
244			groupDetectTimeout = 300 * time.Millisecond
245			t.Cleanup(func() { groupDetectTimeout = old })
246		}
247		cases := []struct {
248			name   string
249			format func(t *testing.T) http.HandlerFunc
250		}{
251			{"server error", func(*testing.T) http.HandlerFunc { return replyStatus(http.StatusInternalServerError) }},
252			{"bad gateway", func(*testing.T) http.HandlerFunc { return replyStatus(http.StatusBadGateway) }},
253			{"not found", func(*testing.T) http.HandlerFunc { return replyStatus(http.StatusNotFound) }},
254			{"unreadable reply", func(*testing.T) http.HandlerFunc {
255				return func(w http.ResponseWriter, _ *http.Request) { _, _ = w.Write([]byte("<html>")) }
256			}},
257			{"connection closed", func(*testing.T) http.HandlerFunc {
258				return func(w http.ResponseWriter, _ *http.Request) {
259					conn, _, err := w.(http.Hijacker).Hijack()
260					if err == nil {
261						_ = conn.Close()
262					}
263				}
264			}},
265			{"deadline", func(t *testing.T) http.HandlerFunc {
266				shorten(t)
267				return func(_ http.ResponseWriter, r *http.Request) { <-r.Context().Done() }
268			}},
269		}
270		for _, tc := range cases {
271			t.Run(tc.name+"/with what was last known", func(t *testing.T) {
272				home := isolateGroupHome(t)
273				known := knownMembers()
274				seedGroup(t, &known, &cache.RegistryGroupRefusal{At: at(4), Status: http.StatusForbidden})
275				before, err := os.ReadFile(groupCacheFile(home))
276				if err != nil {
277					t.Fatalf("reading the seeded cache: %v", err)
278				}
279				reg := nexusGroupServer(t, tc.format(t))
280	
281				msg := runDetect(t, reg)
282	
283				if msg.Err == nil {
284					t.Fatal("msg.Err = nil: an unreachable manager is a failed discovery")
285				}
286				if errors.Is(msg.Err, registrymgr.ErrMembersRefused) {
287					t.Errorf("msg.Err = %v: only a 401 or 403 is a refusal, this is a transient failure", msg.Err)
288				}
289				after, err := os.ReadFile(groupCacheFile(home))
290				if err != nil {
291					t.Fatalf("reading the cache after: %v", err)
292				}
293				if !bytes.Equal(before, after) {
294					t.Errorf("the cache file changed on a failed discovery:\nbefore: %s\nafter:  %s", before, after)
295				}
296			})
297			t.Run(tc.name+"/never asked before", func(t *testing.T) {
298				home := isolateGroupHome(t)
299				reg := nexusGroupServer(t, tc.format(t))
300	
301				msg := runDetect(t, reg)
302	
303				if msg.Err == nil || errors.Is(msg.Err, registrymgr.ErrMembersRefused) {
304					t.Fatalf("msg.Err = %v, want a transient failure that is not a refusal", msg.Err)
305				}
306				if data, err := os.ReadFile(groupCacheFile(home)); err == nil {
307					// Opening the cache may create it; it must hold neither a listing nor a refusal.
308					c := openGroupCache(t)
309					if c.Get(groupSlug) != nil || c.Refusal(groupSlug) != nil {
310						t.Errorf("the cache holds an entry after a failed discovery: %s", data)
311					}
312				}
313			})
314		}
315	}
