347	func TestTheHandlerRecordsARefusalAndLeavesTheKnownMembersAlone(t *testing.T) {
348		for _, tc := range []struct {
349			name string
350			err  error
351			want cache.RegistryGroupRefusal
352		}{
353			{"account", refusalOf(403, false), cache.RegistryGroupRefusal{At: at(7), Status: 403}},
354			{"anonymous", refusalOf(401, true), cache.RegistryGroupRefusal{At: at(7), Status: 401, Anonymous: true}},
355			{"wrapped", fmt.Errorf("discovery: %w", refusalOf(403, false)), cache.RegistryGroupRefusal{At: at(7), Status: 403}},
356		} {
357			t.Run(tc.name, func(t *testing.T) {
358				m := groupModel(t)
359	
360				m = feed(t, m, RegistryGroupDetectedMsg{
361					RegistryURL: "registry.example.com", Slug: "prod", Err: tc.err, At: at(7),
362				})
363	
364				if got, ok := m.groupRefusals["prod"]; !ok || got != tc.want {
365					t.Errorf("groupRefusals[prod] = %+v (present %v), want %+v with the instant of msg.At", got, ok, tc.want)
366				}
367				entry := m.groupCache["prod"]
368				if len(entry.Members) != 2 || !entry.DiscoveredAt.Equal(at(3)) {
369					t.Errorf("groupCache[prod] = %+v, want the 2 members and the date last known", entry)
370				}
371				if m.refreshingGroups["prod"] {
372					t.Error("the discovery is still shown as running after the refusal")
373				}
374				if m.footer.Level() == sharedcomponents.LevelError {
375					t.Errorf("footer is at level Error (%q): a refusal is a warning, the failure case is the red one", m.footer.Text())
376				}
377			})
378		}
379	}
