			if want := "denied · " + ago; got != want {
				t.Errorf("nothing listed: cell = %q, want %q", got, want)
			}
			wantRefusalText(t, "cell", got)

			got = refusedMembersCell(groupRefusalView{Refusal: tc.refusal, Known: 3})
