				t.Errorf("3 known: cell = %q, want the state first", got)
			}
			wantAll(t, "3 known: cell", got, "3 known", ago)
			wantRefusalText(t, "cell", got)
		})
	}
}

func TestRefusedStatusLineWording(t *testing.T) {
