	m := feed(t, New(cfg), tea.WindowSizeMsgOf(180, 30),
		ImagesListMsg{Images: imageFixtures()}, NetworksListMsg{Networks: networkFixtures()}, VolumesListMsg{Volumes: volumeFixtures()})
